{"function":"() => {
  const text = document.body.innerText;
  const blocks = text.split(/(?=\n(?:在售|缺货|不可售|在搜索结果中禁止显示|已停售)\n)/);
  return blocks.slice(1).map(b => {
    const asin = (b.match(/ASIN\n([A-Z0-9]+)/) || [])[1];
    const sku = (b.match(/SKU\n([^\n]+)/) || [])[1];
    const sales = (b.match(/销售额\n([^\n]+)/) || [])[1];
    const units = (b.match(/售出件数\n([^\n]+)/) || [])[1];
    const views = (b.match(/页面浏览量\n([^\n]+)/) || [])[1];
    const rank = (b.match(/销售排名\n([^\n]+)/) || [])[1];
    const avail = (b.match(/可售\n(\d+)/) || [])[1];
    const inbound = (b.match(/入库\n(\d+)/) || [])[1];
    const reserved = (b.match(/预留\n(\d+)/) || [])[1];
    const fbm = b.includes('卖家自配送');
    const price = (b.match(/推荐报价\n([^\n]+)/) || [])[1];
    const fee = (b.match(/总费用\n([^\n]+)/) || [])[1];
    const status = b.trim().split('\n')[0];
    return { status, asin, sku, sales, units, views, rank, avail, inbound, reserved, fbm, price, fee };
  });
}","pageId":4,"toolSummary":"Parse top 50 selling listings into structured JSON","waitForStableDom":false}

