tool_calls.arguments_json:
{"function":"async () => {
  const cell4 = document.querySelector('[row-index="4"] [col-id="country"]');
  if (cell4) cell4.click();
  document.querySelector('.ag-body-viewport').scrollTop = 0;
  document.querySelector('.ag-body-vertical-scroll-viewport').scrollTop = 0;
  await new Promise(r => setTimeout(r, 600));
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  const rowIdx = '3';
  const expectedName = 'SP_305满胶100_KW BROAD 1_20250811';
  const nameCell = document.querySelector(`[row-index="${rowIdx}"] [col-id="name"]`);
  if (!nameCell || !nameCell.innerText.includes(expectedName)) {
    return { error: 'name mismatch', visible: Array.from(document.querySelectorAll('[col-id="name"]')).map(c => c.innerText) };
  }
  const budgetCell = document.querySelector(`[row-index="${rowIdx}"] [col-id="budget"]`);
  const beforeText = budgetCell.innerText.replace(/\n+/g, ' ').trim();
  budgetCell.querySelector('button').click();
  await new Promise(r => setTimeout(r, 600));
  const input = document.querySelector('input[aria-label="enter amount in US$"]');
  nativeInputValueSetter.call(input, '10');
  input.dispatchEvent(new Event('input', { bubbles: true }));
  input.dispatchEvent(new Event('change', { bubbles: true }));
  await new Promise(r => setTimeout(r, 300));
  const saveBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText.trim() === '保存');
  saveBtn.click();
  await new Promise(r => setTimeout(r, 1500));
  const afterText = document.querySelector(`[row-index="${rowIdx}"] [col-id="budget"]`)?.innerText.replace(/\n+/g, ' ').trim();
  const statusText = document.querySelector(`[row-index="${rowIdx}"] [col-id="status"]`)?.innerText.trim();
  return { rowIdx, expectedName, beforeText, afterText, statusText };
}","pageId":5,"toolSummary":"Update daily budget for SP_305满胶100_KW BROAD 1_20250811 to $10.00","waitForStableDom":true}

