    if (closeBtn) closeBtn.click();
    await new Promise(r => setTimeout(r, 500));
  }
  return results;
}","pageId":5,"toolSummary":"Click Fix Suppressed Listing on all 3 items to read suppression reasons","waitForStableDom":true}

