  await new Promise(r => setTimeout(r, 3000));
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  async function updateCampaignBudget(targetName, newBudget) {
    for (const scrollPos of [0, 200, 400]) {
      const v1 = document.querySelector('.ag-body-viewport');
      const v2 = document.querySelector('.ag-body-vertical-scroll-viewport');
      if (v1) v1.scrollTop = scrollPos;
      if (v2) v2.scrollTop = scrollPos;
      await new Promise(r => setTimeout(r, 400));
      const matchCell = Array.from(document.querySelectorAll('[col-id="name"]')).find(c => c.innerText.includes(targetName));
      if (matchCell) {
        const rowIdx = matchCell.closest('[row-index]').getAttribute('row-index');
        const budgetCell = document.querySelector(`[row-index="${rowIdx}"] [col-id="budget"]`);
        const beforeText = budgetCell.innerText.replace(/\n+/g, ' ').trim();
        const btn = budgetCell.querySelector('button');
        btn.click();
        await new Promise(r => setTimeout(r, 600));
        const input = document.querySelector('input[aria-label="enter amount in US$"]');
        if (!input) return { targetName, rowIdx, error: 'input not found' };
        nativeInputValueSetter.call(input, String(newBudget));
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
        await new Promise(r => setTimeout(r, 300));
        const saveBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText.trim() === '保存');
        if (!saveBtn) return { targetName, rowIdx, error: 'saveBtn not found' };
        saveBtn.click();
        await new Promise(r => setTimeout(r, 1500));
        const afterText = document.querySelector(`[row-index="${rowIdx}"] [col-id="budget"]`)?.innerText.replace(/\n+/g, ' ').trim();
        const statusText = document.querySelector(`[row-index="${rowIdx}"] [col-id="status"]`)?.innerText.trim();
        return { targetName, rowIdx, fullText: matchCell.innerText.replace(/\n+/g, ' '), beforeText, afterText, statusText };
      }
    }
    return { targetName, error: 'not found after scrolling' };
  }
  const r1 = await updateCampaignBudget('SD_再营销_20250721', '6');
  const r2 = await updateCampaignBudget('SP_305满胶300_KW BROAD_20250411', '5');
  const r3 = await updateCampaignBudget('SP_305满胶300_AUTO 紧_20250411', '5');
  return [r1, r2, r3];
}","pageId":6,"toolSummary":"Increase daily budgets for the 3 high-ROI campaigns in Campaign Manager","waitForStableDom":true}

